async function fetchWithRetry(url, options = {}, maxRetries = 3) {
  const timeoutMs = options.timeout || 10000;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), timeoutMs);
      const mergedOptions = { ...options, signal: controller.signal };
      delete mergedOptions.timeout;
      const response = await fetch(url, mergedOptions);
      clearTimeout(timeout);

      if (response.ok || response.status < 500) {
        if (typeof hideReconnectNotice === 'function') {
          hideReconnectNotice();
        }
        return response;
      }

      if (attempt < maxRetries) {
        if (attempt === 0 && typeof showReconnectNotice === 'function') {
          showReconnectNotice();
        }
        await new Promise(resolve => setTimeout(resolve, 1000 * Math.pow(2, attempt)));
      } else {
        if (typeof hideReconnectNotice === 'function') {
          hideReconnectNotice();
        }
        return response;
      }
    } catch (error) {
      if (attempt === maxRetries) {
        if (typeof hideReconnectNotice === 'function') {
          hideReconnectNotice();
        }
        throw error;
      }
      if (attempt === 0 && typeof showReconnectNotice === 'function') {
        showReconnectNotice();
      }
      await new Promise(resolve => setTimeout(resolve, 1000 * Math.pow(2, attempt)));
    }
  }
}

function showReconnectNotice() {
  let banner = document.getElementById('reconnect-banner');
  if (!banner) {
    banner = document.createElement('div');
    banner.id = 'reconnect-banner';
    banner.className = 'reconnect-banner';
    banner.setAttribute('role', 'status');
    banner.setAttribute('aria-live', 'polite');
    banner.textContent = 'Tentative de reconnexion…';
    document.body.prepend(banner);
  }
}

function hideReconnectNotice() {
  const banner = document.getElementById('reconnect-banner');
  if (banner) banner.remove();
}

if (typeof window !== 'undefined') {
  window.fetchWithRetry = fetchWithRetry;
  window.showReconnectNotice = showReconnectNotice;
  window.hideReconnectNotice = hideReconnectNotice;
}

function dashboardElement(tag, options = {}) {
  const node = document.createElement(tag);
  if (options.className) node.className = options.className;
  if (options.text !== undefined) node.textContent = String(options.text);
  if (options.attrs) {
    for (const [name, value] of Object.entries(options.attrs)) {
      if (value !== undefined && value !== null) node.setAttribute(name, String(value));
    }
  }
  if (options.dataset) {
    for (const [name, value] of Object.entries(options.dataset)) {
      node.dataset[name] = String(value);
    }
  }
  if (options.children) node.append(...options.children);
  return node;
}

function dashboardButton(label, className, dataset = {}) {
  return dashboardElement("button", {
    className,
    text: label,
    attrs: { type: "button" },
    dataset,
  });
}

const dashboardStateIcons = {
  loading: '<path d="M20 12a8 8 0 1 1-2.34-5.66M20 4v5h-5"></path>',
  empty: '<path d="M4.75 6.75h14.5v10.5H4.75z"></path><path d="M8 10h8M8 14h5"></path>',
  error: '<path d="M12 8v5"></path><path d="M12 17h.01"></path><path d="M10.3 4.7 3.5 17a2 2 0 0 0 1.75 3h13.5a2 2 0 0 0 1.75-3L13.7 4.7a1.95 1.95 0 0 0-3.4 0z"></path>',
  unavailable: '<path d="M12 4.75 18.5 7v5.25c0 4.2-2.6 6.8-6.5 7.99-3.9-1.19-6.5-3.79-6.5-7.99V7z"></path><path d="m9 9 6 6M15 9l-6 6"></path>',
};

function dashboardState({ type = "empty", title = "", message = "", compact = false } = {}) {
  const icon = dashboardElement("span", {
    className: "system-state-icon",
    attrs: { "aria-hidden": "true" },
  });
  icon.innerHTML = `<svg viewBox="0 0 24 24">${dashboardStateIcons[type] || dashboardStateIcons.empty}</svg>`;
  const children = [icon];
  if (title) children.push(dashboardElement("p", { className: "system-state-title", text: title }));
  if (message) children.push(dashboardElement("p", { className: "system-state-message", text: message }));
  return dashboardElement("div", {
    className: `system-state ${type}${compact ? " compact" : ""}`,
    attrs: { role: type === "error" || type === "unavailable" ? "alert" : "status" },
    children,
  });
}

if (typeof window !== "undefined") {
  window.DashboardDOM = Object.freeze({
    element: dashboardElement,
    button: dashboardButton,
    state: dashboardState,
  });
}

const DASHBOARD_NAV_DEFAULT_PREFIXES = {
  torrent: "/torrent-panel",
  prowlarr: "/prowlarr-panel",
  cloud: "/cloud-panel",
  activity: "/activity",
  storage: "/storage-panel",
  media: "/media-panel",
  health: "/health",
};

function normalizeDashboardPrefix(value, fallback = "") {
  const prefix = String(value || fallback || "").replace(/\/$/, "");
  return prefix === "/" ? "" : prefix;
}

function dashboardPrefixConfig(config = {}) {
  return {
    torrent: normalizeDashboardPrefix(config.torrentPanelPrefix, DASHBOARD_NAV_DEFAULT_PREFIXES.torrent),
    prowlarr: normalizeDashboardPrefix(config.prowlarrPanelPrefix, DASHBOARD_NAV_DEFAULT_PREFIXES.prowlarr),
    cloud: normalizeDashboardPrefix(config.cloudPanelPrefix, DASHBOARD_NAV_DEFAULT_PREFIXES.cloud),
    activity: normalizeDashboardPrefix(config.activityPrefix, DASHBOARD_NAV_DEFAULT_PREFIXES.activity),
    storage: normalizeDashboardPrefix(config.storagePrefix, DASHBOARD_NAV_DEFAULT_PREFIXES.storage),
    media: normalizeDashboardPrefix(config.mediaPrefix, DASHBOARD_NAV_DEFAULT_PREFIXES.media),
    health: normalizeDashboardPrefix(config.healthPrefix, DASHBOARD_NAV_DEFAULT_PREFIXES.health),
  };
}

function dashboardNavHref(key, prefixes) {
  const withSlash = (prefix) => `${prefix || ""}/`;
  if (key === "home") return `${withSlash(prefixes.torrent)}?view=home`;
  if (key === "torrent") return withSlash(prefixes.torrent);
  if (key === "prowlarr") return withSlash(prefixes.prowlarr);
  if (key === "cloud") return withSlash(prefixes.cloud);
  if (key === "media") return withSlash(prefixes.media);
  if (key === "storage") return withSlash(prefixes.storage);
  if (key === "health") return withSlash(prefixes.health);
  if (key === "activity") return withSlash(prefixes.activity);
  return "";
}

function configureDashboardNavigation(config = {}, current = "") {
  const prefixes = dashboardPrefixConfig(config);
  const links = document.querySelectorAll(".nav [data-shell-nav]");
  links.forEach((link) => {
    const key = link.dataset.shellNav;
    const href = dashboardNavHref(key, prefixes);
    if (href) link.href = href;
    if (current) {
      if (key === current) link.setAttribute("aria-current", "page");
      else link.removeAttribute("aria-current");
    }
  });
  return prefixes;
}

if (typeof window !== "undefined") {
  window.DashboardNavigation = {
    configure: configureDashboardNavigation,
    href: dashboardNavHref,
    normalizePrefix: normalizeDashboardPrefix,
    prefixes: dashboardPrefixConfig,
  };
}

function trapFocus(dialog) {
  if (!dialog || dialog.dataset.focusTrapReady === "true") return;
  dialog.dataset.focusTrapReady = "true";
  dialog.addEventListener("keydown", function handler(event) {
    if (event.key !== "Tab") return;
    const focusable = [...dialog.querySelectorAll(
      'button:not(:disabled), [href], input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex]:not([tabindex="-1"])'
    )].filter(node => !node.hidden);
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (!first || !last) return;
    if (event.shiftKey) {
      if (document.activeElement === first) {
        event.preventDefault();
        last?.focus();
      }
    } else {
      if (document.activeElement === last) {
        event.preventDefault();
        first?.focus();
      }
    }
  });
}

function openDialog(dialog, trigger) {
  if (!dialog) return;
  dialog._lastFocus = trigger || document.activeElement;
  trapFocus(dialog);
  dialog.showModal();
  const first = dialog.querySelector(
    '[autofocus], button:not(:disabled), [href], input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex]:not([tabindex="-1"])'
  );
  first?.focus();
  dialog.addEventListener("close", function restore() {
    dialog._lastFocus?.focus?.();
    dialog.removeEventListener("close", restore);
  }, { once: true });
}

if (typeof window !== "undefined") {
  window.trapFocus = trapFocus;
  window.openDialog = openDialog;
}

